<script lang="ts">
    export let posts: {title:string;description:string;category:string;date:string;href:string;cover:string}[];
    let mode='A', hovered=-1;
    const versions=[{id:'A',name:'书目',description:'无封面。日期、标题与简短摘要组成单列，阅读顺序最清楚。'},{id:'B',name:'双页',description:'无封面。保留双栏阅读节奏，用留白和字号区分重点。'}];
</script>
<section class="post-prototype">
    <div class="prototype-tools"><div><h1>首页文章排布</h1><p>{versions.find(v=>v.id===mode)?.description}</p></div><nav aria-label="方案">{#each versions as version}<button class:chosen={mode===version.id} on:click={()=>{mode=version.id;hovered=-1;}}>{version.id} · {version.name}</button>{/each}</nav></div>
    <div class="prototype-canvas" class:two-page={mode==='B'} class:margin-note={mode==='C'}>
        <header><span>最新文章</span><small>写下所学，也留下思考。</small></header>
        <div class="preview-body"><div class="writing-list">{#each posts as post,index}<a href={post.href} class="writing" on:mouseenter={()=>hovered=index} on:mouseleave={()=>hovered=-1} on:focus={()=>hovered=index} on:blur={()=>hovered=-1}><div class="writing-meta"><time>{post.date}</time><span>{post.category}</span></div><div class="writing-text"><h2>{post.title}</h2><p>{post.description}</p>{#if mode==='B'}<span class="read-mark">阅读全文 ↗</span>{/if}</div><span class="writing-arrow" aria-hidden="true">↗</span></a>{/each}</div>
        {#if mode==='C'}<aside aria-hidden="true"><div class="photo-note" class:revealed={hovered>=0}>{#if hovered>=0}<img src={posts[hovered].cover} alt=""/><span>{posts[hovered].category}</span>{:else}<span class="note-mark">＊</span><p>文字之间，偶有风景。</p>{/if}</div></aside>{/if}</div>
    </div>
</section>
